template <typename T>
class MyArray {
    T* data;

public:
    // Alias definitions (Zero runtime cost)
    using value_type      = T;
    using size_type       = size_t;

    // Standard Iterator Typedefs (usually T* for simple containers)
    using iterator        = T*;
    using const_iterator  = const T*;

    // Use in API: enhances readability
    iterator begin() { return data; }
    const_iterator cbegin() const { return data; }
};

